MATCH_MACRO = """{% macro render_match(m, is_admin, current_user, logs_dict={}, pred=None) %}{% set is_participant = current_user and (m.t1_user_id == current_user.id or m.t2_user_id == current_user.id) %}<div class="match-card navy-card p-4 border border-white/5 relative overflow-hidden flex flex-col justify-between" data-round="{{ m.round_num }}" data-team1="{{ m.team1_id }}" data-team2="{{ m.team2_id }}" data-stage="{{ m.stage }}"><div class="flex justify-between items-center border-b border-white/5 pb-2 mb-3"><span class="text-[9px] font-black text-slate-500 uppercase tracking-widest">KOLO {{ m.round_num }} • {{ m.stage|upper }}</span><div class="flex gap-1.5 shrink-0"><a href="/match/{{ m.id }}/chat" class="text-blue-500 p-1"><i data-lucide="message-square" class="w-4 h-4"></i></a></div></div><div class="grid grid-cols-3 items-center text-center my-auto"><div class="flex flex-col items-center gap-1.5 min-w-0"><div class="w-11 h-11 rounded-xl flex items-center justify-center border border-white/10 cursor-pointer hover:scale-105 transition-transform shadow-inner" style="background-color: {{ m.t1_color }}" onclick="openLogoModal('{{m.t1_logo}}', '{{m.t1_color}}')">{% if m.t1_logo and 'static' in m.t1_logo %}<img src="{{m.t1_logo}}" class="w-full h-full object-contain p-1">{% else %}<span class="text-lg">{{m.t1_logo}}</span>{% endif %}</div><p class="text-[10px] font-black uppercase truncate w-full theme-text-main">{{ m.t1_name }}</p></div><div class="text-2xl font-black italic text-white">{% if m.status == 'finished' %}{{ m.score1 }}:{{ m.score2 }}{% elif m.status == 'proposed' %}<span class="text-orange-500">{{ m.proposed_score1 }}:{{ m.proposed_score2 }}</span>{% else %}-:-{% endif %}</div><div class="flex flex-col items-center gap-1.5 min-w-0"><div class="w-11 h-11 rounded-xl flex items-center justify-center border border-white/10 cursor-pointer hover:scale-105 transition-transform shadow-inner" style="background-color: {{ m.t2_color }}" onclick="openLogoModal('{{m.t2_logo}}', '{{m.t2_color}}')">{% if m.t2_logo and 'static' in m.t2_logo %}<img src="{{m.t2_logo}}" class="w-full h-full object-contain p-1">{% else %}<span class="text-lg">{{m.t2_logo}}</span>{% endif %}</div><p class="text-[10px] font-black uppercase truncate w-full theme-text-main">{{ m.t2_name }}</p></div></div><div class="mt-4 pt-3 border-t border-white/5 flex flex-col gap-2">{% if m.status == 'planned' and (is_participant or is_admin) %}<form action="/match/{{ m.id }}/propose" method="POST" class="flex gap-2"><input type="number" name="s1" placeholder="T1" required class="w-full rounded-lg p-2 text-center text-xs bg-slate-900 text-white"><input type="number" name="s2" placeholder="T2" required class="w-full rounded-lg p-2 text-center text-xs bg-slate-900 text-white"><button class="bg-blue-600 px-3 rounded-lg text-white font-bold text-xs"><i data-lucide="check" class="w-4 h-4"></i></button></form>{% elif m.status == 'proposed' and is_admin %}<div class="flex gap-2"><form action="/match/{{ m.id }}/approve" method="POST" class="flex-1"><button class="w-full bg-green-600 text-white py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest">Schválit</button></form><form action="/match/{{ m.id }}/reset" method="POST" class="flex-1"><button class="w-full bg-red-900/40 text-red-500 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest">Odmítnout</button></form></div>{% elif m.status == 'finished' and is_admin %}<form action="/match/{{ m.id }}/reset" method="POST" class="w-full"><button class="w-full bg-slate-800 text-slate-400 py-1.5 rounded-lg text-[8px] font-black uppercase border border-white/5">Resetovat Zápas</button></form>{% endif %}</div></div>{% endmacro %}"""
